/**
 * smooth-scroll-gen.ts — the Smooth Scroll (Lenis) RUNTIME in user source.
 *
 * Two generated files at the app root, beside the root layout:
 *   - app/smooth-scroll.ts            → the SMOOTH_SCROLL data map (editor writes it)
 *   - app/smooth-scroll-controller.tsx → <SmoothScroll />, a client controller
 * and `<SmoothScroll />` is mounted once inside `<body>` of `app/layout.tsx`.
 *
 * Why the ROOT layout and not the LayoutClient page transitions use: every
 * project has a root layout, template or not (an imported site without a
 * an imported layout has no route group), and the editor preview renders the same
 * layout chain a published site does. The controller renders nothing.
 *
 * The controller carries its own route resolver (a hand-mirrored copy of
 * resolveSmoothScroll) so the deployed file has no editor imports.
 */

import { trace } from '@/shared/debug-trace';
import { projectFS } from '../project/project-fs';
import { serializeSmoothScroll } from '../project/smooth-scroll-config';

import { SMOOTH_SCROLL_DATA_PATH, SMOOTH_SCROLL_CONTROLLER_PATH } from './smooth-scroll-layout';
export { SMOOTH_SCROLL_DATA_PATH, SMOOTH_SCROLL_CONTROLLER_PATH };

/** Bump when the controller's logic changes: an outdated copy is rewritten on the next edit. */
export const SMOOTH_SCROLL_MARKER = '@smooth-scroll v3';

export const SMOOTH_SCROLL_CONTROLLER_SOURCE = `'use client';
// @generated by Revyme — Smooth Scroll controller. Do not edit. ${SMOOTH_SCROLL_MARKER}
import * as React from 'react';
import { usePathname } from 'next/navigation';
import Lenis from 'lenis';
import { SMOOTH_SCROLL } from './smooth-scroll';

// Lenis's own stylesheet (lenis/dist/lenis.css), inlined so the controller is
// one self-contained file with no CSS import to resolve.
const LENIS_CSS = 'html.lenis,html.lenis body{height:auto}'
  + '.lenis:not(.lenis-autoToggle).lenis-stopped{overflow:clip}'
  + '.lenis [data-lenis-prevent],.lenis [data-lenis-prevent-wheel],.lenis [data-lenis-prevent-touch],'
  + '.lenis [data-lenis-prevent-vertical],.lenis [data-lenis-prevent-horizontal]{overscroll-behavior:contain}'
  + '.lenis.lenis-smooth iframe{pointer-events:none}'
  + '.lenis.lenis-autoToggle{transition-property:overflow;transition-duration:1ms;transition-behavior:allow-discrete}';

// Elements whose own wheel and keys must not be taken over by the page.
const PREVENT_WHEEL = '[data-lenis-prevent], [data-lenis-prevent-wheel]';
const EDITABLE = 'input, textarea, select, [contenteditable]:not([contenteditable="false"])';
// Widgets that use the arrow keys, Home/End or Space themselves, and modal dialogs, whose keys
// belong to the dialog and not to the page behind it.
const OWNS_KEYS = '[role="slider"], [role="spinbutton"], [role="listbox"], [role="option"], [role="combobox"], '
  + '[role="tablist"], [role="tab"], [role="menu"], [role="menubar"], [role="menuitem"], [role="radiogroup"], '
  + '[role="radio"], [role="tree"], [role="treegrid"], [role="grid"], video, audio, dialog[open], [aria-modal="true"]';
// Space activates these; on a link it scrolls, as natively.
const INTERACTIVE = 'button, summary, [role="button"], [role="checkbox"], [role="switch"]';
// After every layout of an editorial flow (its width changes with its pages).
const FLOW_LAYOUT_EVENT = 'revyme:layout';
const LINE_PX = 20;   // one wheel "line" (deltaMode 1)
const ARROW_PX = 40;  // one ArrowUp / ArrowDown
const PAGE_SHARE = 0.9;  // Space / PageUp / PageDown, as a share of the viewport width

function routeMatches(route: string, pathname: string): boolean {
  const rs = route.split('/').filter(Boolean);
  const ps = pathname.split('/').filter(Boolean);
  for (let i = 0; i < rs.length; i++) {
    if (/^\\[\\.\\.\\..+\\]$/.test(rs[i])) return true;
    if (i >= ps.length) return false;
    if (/^\\[.+\\]$/.test(rs[i])) continue;
    if (rs[i] !== ps[i]) return false;
  }
  return rs.length === ps.length;
}

function resolve(map: any, pathname: string): any {
  const p = pathname || '/';
  if (map && map.pages && map.pages[p]) return map.pages[p];
  for (const route of Object.keys((map && map.pages) || {})) if (routeMatches(route, p)) return map.pages[route];
  return (map && map.__default) || null;
}

/** Height a classic horizontal scrollbar takes from the bottom of the window (0 for overlay ones). */
function scrollbarX(): number {
  return Math.max(0, window.innerHeight - document.documentElement.clientHeight);
}

/** True when the page overflows sideways and not downwards: a horizontal page. A full-height page
 *  under a classic scrollbar overflows by the scrollbar's height, which does not count. */
function pageScrollsOnlyX(): boolean {
  const el = document.documentElement;
  return el.scrollWidth > el.clientWidth && el.scrollHeight <= el.clientHeight + scrollbarX() + 1;
}

// Page Flow sets this on the page root, per breakpoint: the page reads sideways at this width.
const PAGE_FLOW = '--revyme-page-flow';
function pageFlowsAcross(): boolean {
  const root = document.querySelector('[data-id="root"]');
  return !!root && window.getComputedStyle(root).getPropertyValue(PAGE_FLOW).trim() === 'horizontal';
}

/** True when an element under the pointer can take this vertical wheel itself. */
function insideCanScroll(target: EventTarget | null, deltaY: number): boolean {
  if (!(target instanceof Element)) return false;
  if (target.closest(PREVENT_WHEEL)) return true;
  for (let n: Element | null = target; n && n !== document.body && n !== document.documentElement; n = n.parentElement) {
    const overflowY = window.getComputedStyle(n).overflowY;
    if ((overflowY === 'auto' || overflowY === 'scroll') && n.scrollHeight > n.clientHeight) {
      const room = deltaY > 0 ? n.scrollTop + n.clientHeight < n.scrollHeight - 1 : n.scrollTop > 0;
      if (room) return true;
    }
  }
  return false;
}

export function SmoothScroll() {
  const pathname = usePathname();
  React.useEffect(() => {
    if (typeof window === 'undefined') return;
    // No entry for this page is fine: a Page Flow page still reads sideways, unsmoothed.
    const cfg = resolve(SMOOTH_SCROLL, pathname || '/');
    const horizontalWanted = !!cfg && cfg.orientation === 'horizontal';
    // Width gate: horizontal only while the window is at least horizontalFrom px wide.
    const fromPx = cfg ? Math.round(Number(cfg.horizontalFrom)) : NaN;
    const gate = Number.isFinite(fromPx) && fromPx >= 1 && window.matchMedia
      ? window.matchMedia('(min-width: ' + fromPx + 'px)') : null;
    // Visitors who asked for less motion keep native scrolling (plus the unsmoothed remap below).
    const reduced = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
    const acrossNow = () => (horizontalWanted && (gate ? gate.matches : true)) || pageFlowsAcross();
    let teardown: (() => void) | null = null;
    let across = false;
    let fitSliver = () => {};

    const start = () => {
      if (teardown) teardown();
      teardown = null;
      fitSliver = () => {};
      const horizontal = acrossNow();
      across = horizontal;
      const reduce = !!(reduced && reduced.matches);
      const smooth = !!cfg && cfg.enabled !== false && !reduce;
      const undo: Array<() => void> = [];
      if (!smooth && !horizontal) return;

      let running: any = null;
      if (smooth) {
        const style = document.createElement('style');
        style.setAttribute('data-revyme-lenis', '');
        style.textContent = LENIS_CSS;
        document.head.appendChild(style);
        running = new Lenis({
          duration: Math.max(0.1, Number(cfg.intensity ?? 12) / 10),
          smoothWheel: cfg.smoothWheel !== false,
          syncTouch: cfg.smoothTouch === true,
          orientation: horizontal ? 'horizontal' : 'vertical',
          gestureOrientation: horizontal ? 'both' : 'vertical',
          infinite: cfg.infinite === true,
          autoRaf: true,
          anchors: true,
          allowNestedScroll: true,
          stopInertiaOnNavigate: true,
          // Sideways, the page widens without its box changing (an editorial flow adding pages),
          // which Lenis's cached size never sees: read the width live.
          naiveDimensions: horizontal,
        });
        (window as any).__revymeLenis = running;
        const instance = running;
        undo.push(() => {
          instance.destroy();
          style.remove();
          if ((window as any).__revymeLenis === instance) delete (window as any).__revymeLenis;
        });
      }

      if (horizontal) {
        // A classic scrollbar under a full-height page leaves a sliver of vertical overflow as tall
        // as itself: hidden while that is all there is, so the page never scrolls on both axes. A
        // page that really overflows downwards keeps its vertical scroll.
        const html = document.documentElement;
        const before = html.style.overflowY;
        let hidden = false;
        fitSliver = () => {
          const sliver = html.scrollHeight - html.clientHeight;
          const bar = scrollbarX();
          const hide = bar > 0 && sliver > 0 && sliver <= bar + 1;
          // Written only when the answer changes, so another script's overflow stays its own.
          if (hide === hidden) return;
          hidden = hide;
          html.style.overflowY = hide ? 'hidden' : before;
        };
        fitSliver();
        undo.push(() => { if (hidden) html.style.overflowY = before; });

        // Keys always move a horizontal page on X: through Lenis when it runs, natively otherwise.
        const onKey = (e: KeyboardEvent) => {
          if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey) return;
          const path = typeof e.composedPath === 'function' ? e.composedPath() : [];
          const first = path.length > 0 ? path[0] : e.target;
          const t = first instanceof Element ? first : e.target instanceof Element ? e.target : null;
          if (t && (t.closest(EDITABLE) || t.closest(OWNS_KEYS))) return;
          const viewport = document.documentElement.clientWidth;
          const max = Math.max(0, document.documentElement.scrollWidth - viewport);
          let step = 0;
          let edge: number | null = null;
          switch (e.key) {
            case ' ':
              if (t && t.closest(INTERACTIVE)) return;
              step = (e.shiftKey ? -1 : 1) * PAGE_SHARE * viewport;
              break;
            case 'PageDown':
            case 'PageUp':
              if (e.shiftKey) return;
              step = (e.key === 'PageUp' ? -1 : 1) * PAGE_SHARE * viewport;
              break;
            case 'ArrowDown':
            case 'ArrowUp':
              if (e.shiftKey) return;
              step = (e.key === 'ArrowUp' ? -1 : 1) * ARROW_PX;
              break;
            case 'Home':
            case 'End':
              if (e.shiftKey) return;
              edge = e.key === 'Home' ? 0 : max;
              break;
            default:
              return;
          }
          if (!pageScrollsOnlyX()) return;
          e.preventDefault();
          if (running) {
            // From where Lenis is heading, not where it is: a second Space mid-animation goes a
            // whole page further, and a held arrow does not crawl.
            const from = Number.isFinite(running.targetScroll) ? running.targetScroll : window.scrollX;
            running.scrollTo(Math.min(max, Math.max(0, edge !== null ? edge : from + step)));
          } else {
            // Smoothing switched off on this page, or less motion asked for: no animation.
            const behavior = reduce || (cfg && cfg.enabled === false) ? 'instant' : 'smooth';
            if (edge !== null) window.scrollTo({ left: edge, top: window.scrollY, behavior });
            else window.scrollBy({ left: step, top: 0, behavior });
          }
        };
        window.addEventListener('keydown', onKey);
        undo.push(() => window.removeEventListener('keydown', onKey));

        // Without Lenis, a vertical wheel on a horizontal page moves it on X.
        if (!running) {
          const onWheel = (e: WheelEvent) => {
            if (e.defaultPrevented || e.ctrlKey || e.metaKey || e.shiftKey) return;
            const dy = e.deltaY;
            if (dy === 0 || Math.abs(e.deltaX) >= Math.abs(dy)) return;
            if (!pageScrollsOnlyX() || insideCanScroll(e.target, dy)) return;
            const px = e.deltaMode === 1 ? dy * LINE_PX
              : e.deltaMode === 2 ? dy * document.documentElement.clientWidth
              : dy;
            e.preventDefault();
            window.scrollBy({ left: px, top: 0, behavior: 'instant' });
          };
          window.addEventListener('wheel', onWheel, { passive: false });
          undo.push(() => window.removeEventListener('wheel', onWheel));
        }
      }

      teardown = () => { for (const u of undo) u(); };
    };

    start();
    const onChange = () => start();
    if (gate) gate.addEventListener('change', onChange);
    if (reduced) reduced.addEventListener('change', onChange);
    // A breakpoint can turn the page sideways or back (Page Flow): checked on every resize, and
    // rebuilt only when the answer changes.
    const onResize = () => {
      if (acrossNow() !== across) start();
      else fitSliver();
    };
    window.addEventListener('resize', onResize);
    // An editorial flow laid out again changes the page's width (and so whether a horizontal
    // scrollbar takes height) without any resize.
    window.addEventListener(FLOW_LAYOUT_EVENT, onResize);
    return () => {
      if (gate) gate.removeEventListener('change', onChange);
      if (reduced) reduced.removeEventListener('change', onChange);
      window.removeEventListener('resize', onResize);
      window.removeEventListener(FLOW_LAYOUT_EVENT, onResize);
      if (teardown) teardown();
      teardown = null;
    };
  }, [pathname]);
  return null;
}
`;

/** Write the data module (when missing) and the controller (when missing or outdated). */
export function ensureSmoothScrollScaffold(): void {
  if (projectFS.readFile(SMOOTH_SCROLL_DATA_PATH) == null) {
    projectFS.writeFile(SMOOTH_SCROLL_DATA_PATH, serializeSmoothScroll({ pages: {} }));
  }
  const existing = projectFS.readFile(SMOOTH_SCROLL_CONTROLLER_PATH);
  if (existing == null || !existing.includes(SMOOTH_SCROLL_MARKER)) {
    projectFS.writeFile(SMOOTH_SCROLL_CONTROLLER_PATH, SMOOTH_SCROLL_CONTROLLER_SOURCE);
  }
  trace.action('smooth-scroll-gen:ensure-scaffold', {});
}

export { ensureSmoothScrollInLayout } from './smooth-scroll-layout';
